import { newId, now } from '../core/ids';
import { bestGifMatch, bestRepdbMatch, equipmentFor, type GifCandidate } from '../core/gifMatch';
import { findSimilar } from '../core/similarity';
import type { Exercise, ExerciseKind } from '../core/types';
import { repo } from '.';
import exerciseGifs from './exerciseGifs.json';
import { mergeExercises } from './merge';
import { STARTER_CATALOG_IDS } from './seed';

/** One entry of the bundled exercise library (generated by scripts/build-exercise-catalog.mjs). */
export interface CatalogExercise {
  id: string;
  name: string;
  muscleGroup: string;
  kind: ExerciseKind;
  equipment?: string;
  /** The dataset has no photos for it. */
  noPhotos?: true;
  /** A one-joint lift (the dataset's "mechanic"); compound otherwise. */
  isolation?: true;
}

/**
 * The library's photos (start and end of the movement), from free-exercise-db on GitHub through the jsDelivr CDN,
 * pinned to one commit so they can't change or vanish under us. Too many (~1,500, ~70 KB each) to ship in the app,
 * so they load when shown; the service worker keeps the ones seen. Missing or offline: the image hides itself.
 */
const PHOTOS = 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises';

export function exercisePhotos(catalogId: string): [string, string] {
  return [`${PHOTOS}/${catalogId}/0.jpg`, `${PHOTOS}/${catalogId}/1.jpg`];
}

/** How a library exercise is done, and what it works (free-exercise-db's own file for it). */
export interface ExerciseInfo {
  instructions: string[];
  primaryMuscles: string[];
  secondaryMuscles: string[];
}

const infoCache = new Map<string, Promise<ExerciseInfo | null>>();

/**
 * Fetched when the exercise's pictures are opened rather than bundled (~575 KB for the library), from the same pinned
 * commit as the photos; the service worker keeps it once seen. Null offline or when there's no file.
 */
export function loadExerciseInfo(catalogId: string): Promise<ExerciseInfo | null> {
  let info = infoCache.get(catalogId);
  if (!info) {
    info = fetch(`${PHOTOS}/${encodeURIComponent(catalogId)}.json`)
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => (d && Array.isArray(d.instructions) ? { instructions: d.instructions, primaryMuscles: d.primaryMuscles ?? [], secondaryMuscles: d.secondaryMuscles ?? [] } : null))
      .catch(() => null);
    // A failure (offline) is tried again next time.
    info.then((d) => d || infoCache.delete(catalogId));
    infoCache.set(catalogId, info);
  }
  return info;
}

/**
 * Which pictures exercises get, one style only (an exercise with none gets the dumbbell):
 * - 'repdb': RepDB's free flat illustrations (start and peak of the movement, or one picture for a hold), matched to
 *   the library ahead of time by scripts/match-exercise-repdb.mjs and to names you typed here. Free Tier License v1.0:
 *   commercial use in apps with the "Exercise data by RepDB (repdb.co)" credit in Settings → About.
 * - 'anatomical': ExerciseDB's anatomical GIFs (a 3D figure, working muscles in red). Their free V1 GIFs have no
 *   licence for apps ("All rights reserved"), so kept for testing only.
 * - 'photos': free-exercise-db's photos (Unlicense, but they look like Bodybuilding.com's; check before relying on it).
 */
export type MediaSource = 'repdb' | 'anatomical' | 'photos';
export const MEDIA = 'repdb' as MediaSource;
export const USE_ANATOMICAL = MEDIA === 'anatomical';

const REPDB = 'https://cdn.jsdelivr.net/gh/RepDB/exercise-dataset@f12da458a90f353a86c953f204304d5a8bd98275/images/flat';
export interface RepdbData {
  map: Record<string, string>;
  items: GifCandidate[];
}
let repdbData: Promise<RepdbData> | null = null;
export function loadRepdb(): Promise<RepdbData> {
  repdbData ??= import('./repdb.json').then((m) => m.default as unknown as RepdbData);
  return repdbData;
}
let repdbInfo: Promise<Record<string, { p: string[]; s: string[]; steps: string[] }>> | null = null;
const ucfirst = (w: string) => w.charAt(0).toUpperCase() + w.slice(1);
export async function loadRepdbInfo(id: string): Promise<ExerciseInfo | null> {
  repdbInfo ??= import('./repdbInfo.json').then((m) => m.default);
  const d = (await repdbInfo)[id];
  return d ? { instructions: d.steps, primaryMuscles: d.p.map(ucfirst), secondaryMuscles: d.s.map(ucfirst) } : null;
}

const GIFS = 'https://static.exercisedb.dev/media';

const nameKey = (name: string) => name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
let byName: { catalog: CatalogExercise[]; map: Map<string, CatalogExercise> } | null = null;

/**
 * The library entry whose photos to show for one of your exercises: its own link, else (for exercises made before
 * they were linked) a starter exercise's entry, or a library exercise with the same name. Only for showing photos;
 * nothing is saved.
 */
export function photoIdFor(exercise: Pick<Exercise, 'name' | 'catalogId'>, catalog: CatalogExercise[] | undefined): string | undefined {
  if (exercise.catalogId) return exercise.catalogId;
  const starter = STARTER_CATALOG_IDS.get(exercise.name.trim().toLowerCase());
  if (starter) return starter;
  if (!catalog) return undefined;
  if (byName?.catalog !== catalog) byName = { catalog, map: new Map(catalog.map((c) => [nameKey(c.name), c])) };
  const match = byName.map.get(nameKey(exercise.name));
  return match && !match.noPhotos ? match.id : undefined;
}

let gifIndex: Promise<GifCandidate[]> | null = null;

/** ExerciseDB's exercises (~70 KB), for matching names you typed yourself; only loaded while USE_ANATOMICAL is on. */
export function loadGifIndex(): Promise<GifCandidate[]> {
  gifIndex ??= import('./exerciseGifIndex.json').then((m) => m.default as GifCandidate[]);
  return gifIndex;
}

const matchedByName = new Map<string, string | undefined>();

export interface ExerciseMedia {
  gif?: string;
  photoId?: string;
  frames?: string[];
  repdbId?: string;
  /** The library entry whose instructions to show (`loadExerciseInfo`), whichever picture is shown. */
  infoId?: string;
}

/**
 * The library's exercises use their ahead-of-time match (exerciseGifs.json). Ones you named yourself (no catalogId)
 * are matched by name against ExerciseDB here, once the index has loaded.
 */
export function exerciseMedia(
  exercise: Pick<Exercise, 'name' | 'catalogId' | 'kind' | 'equipment'>,
  catalog: CatalogExercise[] | undefined,
  index: GifCandidate[] | undefined,
  repdb?: RepdbData,
): ExerciseMedia {
  const photoId = photoIdFor(exercise, catalog);
  if (MEDIA === 'repdb') return repdb ? repdbMedia(exercise, photoId, repdb) : {};
  if (!USE_ANATOMICAL) return { photoId, infoId: photoId };
  // While the GIFs are on, one style only: no photos (unmatched exercises get the dumbbell).
  let gifId = photoId ? (exerciseGifs as Record<string, string>)[photoId] : undefined;
  if (!gifId && !exercise.catalogId && index) {
    const key = `${exercise.name.trim().toLowerCase()}|${exercise.equipment ?? ''}|${exercise.kind}`;
    if (!matchedByName.has(key)) {
      const equipment = equipmentFor(exercise.name, exercise.equipment, exercise.kind === 'bodyweight');
      matchedByName.set(key, bestGifMatch(exercise.name, equipment, index).match?.[0]);
    }
    gifId = matchedByName.get(key);
  }
  return gifId ? { gif: `${GIFS}/${gifId}.gif`, infoId: photoId } : {};
}

const repdbByName = new Map<string, GifCandidate | undefined>();

function repdbMedia(exercise: Pick<Exercise, 'name' | 'catalogId' | 'kind' | 'equipment'>, photoId: string | undefined, repdb: RepdbData): ExerciseMedia {
  let item = photoId && repdb.map[photoId] ? repdb.items.find((i) => i[0] === repdb.map[photoId]) : undefined;
  if (!item && !exercise.catalogId) {
    const key = `${exercise.name.trim().toLowerCase()}|${exercise.equipment ?? ''}|${exercise.kind}`;
    if (!repdbByName.has(key)) {
      const equipment = equipmentFor(exercise.name, exercise.equipment, exercise.kind === 'bodyweight');
      repdbByName.set(key, bestRepdbMatch(exercise.name, equipment, repdb.items).match);
    }
    item = repdbByName.get(key);
  }
  if (!item) return {};
  const id = item[0];
  const frames = item[3] ? [`${REPDB}/${id}-main.webp`] : [`${REPDB}/${id}-start.webp`, `${REPDB}/${id}-peak.webp`];
  return { frames, repdbId: id };
}

export function thumbnailOf(media: ExerciseMedia): string | undefined {
  return media.frames?.[0] ?? media.gif ?? (media.photoId ? exercisePhotos(media.photoId)[0] : undefined);
}

